// O agente devolve em `output` na maioria das versões, `text` em algumas.
const entrada = $input.first().json;
const answer = entrada.output ?? entrada.text ?? '';

const ctx = $('Code: Monta Prompt').first().json;
const chunks = ctx.chunks || [];

// Quais marcadores [N] o modelo escreveu de fato
const usedMarkers = new Set();
for (const m of String(answer).matchAll(/\[(\d{1,2})\]/g)) {
  usedMarkers.add(parseInt(m[1]));
}

const todos = chunks.map((c, i) => ({ c, marker: i + 1 }));
const citados = todos.filter(({ marker }) => usedMarkers.has(marker));

// A rede só vale quando a resposta parece ter usado os documentos: texto
// substancial e trecho de boa similaridade. Uma frase curta de retorno
// ("qual tema?") não cita nada, e mostrar fonte nela é mentir sobre a origem.
const topSim = chunks.reduce((m, c) => Math.max(m, c.similarity || 0), 0);
const respostaSubstancial = String(answer).trim().length >= 400;
const escolhidos = citados.length
  ? citados
  : (respostaSubstancial && topSim >= 0.45 ? todos.slice(0, 3) : []);

const citations = escolhidos.map(({ c, marker }) => ({
  id: String(c.id),
  sourceType: c.source_type || 'document',
  title: c.title || '',
  detail: c.page ? 'Página ' + c.page : (c.folder_name || ''),
  relevance: Math.round((c.similarity || 0) * 100) / 100,
  snippet: (c.content || '').slice(0, 320),
  reference: citados.length ? '[' + marker + ']' : null,
  marker: citados.length ? marker : undefined,
  documentId: c.document_id || null,
  folderId: c.folder_id || null,
  folderName: c.folder_name || null,
  page: c.page || null,
}));

// Confiança: melhor similaridade + quantos trechos fortes vieram
const sims = chunks.map(c => c.similarity || 0).sort((a, b) => b - a);
const top = sims[0] ?? 0;
const fortes = sims.filter(s => s >= 0.4).length;
const level = (top >= 0.55 && fortes >= 2) ? 'muito_alta'
            : top >= 0.5 ? 'alta'
            : top >= 0.4 ? 'media'
            : 'baixa';

// Este é o corpo da resposta do webhook — o formato que a edge function espera.
return [{
  json: {
    conversationId: ctx.conversationId,
    answer: String(answer),
    citations,
    confidence: { level, score: Math.round(top * 100) / 100 },
  }
}];

const cfg = $('Code: Modo & Configs').first().json;

// 1. Histórico — vem pronto da edge function, já compactado.
const historyItems = (Array.isArray(cfg.history) ? cfg.history : [])
  .filter(m => m && m.role && m.content);

// 2. Chunks da busca. Com responseFormat: text o n8n põe o corpo em
//    `json.data`; dependendo da versão vem em `body`, ou já parseado.
//    Falha alto de propósito: erro engolido aqui vira "não encontrei nada".
const httpNode = $('HTTP: Busca Chunks').first();
const bruto = httpNode.json;
const corpo = typeof bruto === 'string' ? bruto : (bruto.data ?? bruto.body ?? bruto);

let rows;
try {
  rows = typeof corpo === 'string' ? JSON.parse(corpo) : corpo;
} catch (e) {
  throw new Error('A busca não devolveu JSON: ' + String(corpo).slice(0, 300));
}
if (!Array.isArray(rows)) {
  throw new Error('A busca devolveu formato inesperado: ' + JSON.stringify(rows).slice(0, 300));
}

// 3. Normaliza e filtra por similaridade
const minSim = cfg.minSimilarity ?? 0.25;
const chunks = rows
  .filter(r => (r.similarity ?? 0) >= minSim)
  .map(r => ({
    id: r.id,
    content: r.content || '',
    similarity: r.similarity || 0,
    title: (r.metadata && r.metadata.file_name) || 'Documento',
    document_id: (r.metadata && r.metadata.file_id) || null,
    folder_name: (r.metadata && r.metadata.folder_path) || null,
    file_extension: (r.metadata && r.metadata.file_extension) || null,
    page: (r.metadata && r.metadata.page) || null,
    source_type: 'document',
    reference: null,
    folder_id: null,
  }));

// 4. Contexto com as tags [1], [2] explícitas
const context = chunks.length
  ? chunks.map((c, i) => `[${i + 1}] Documento: ${c.title}\nConteúdo: ${c.content}`).join('\n\n---\n\n')
  : 'Nenhum documento encontrado.';

// Sem trecho, o modelo tende a responder de cabeça — e num diagnóstico
// resposta plausível sem fonte é pior que resposta nenhuma.
const semFonte = chunks.length
  ? ''
  : '\n\nATENÇÃO: nenhum trecho foi recuperado para esta pergunta. NÃO responda ' +
    'com conhecimento próprio sobre o assunto. Diga que não encontrou respaldo ' +
    'nos documentos indexados e, se houver histórico, responda apenas com base nele, ' +
    'deixando claro que é o que o consultor contou e não a metodologia da casa.';

const artifactState = cfg.artifactOutline
  ? '\n\nDOCUMENTO ATUAL (sumário):\n' + cfg.artifactOutline +
    (cfg.artifactBodies ? '\n\nCONTEÚDO INTEGRAL DAS SEÇÕES RELEVANTES:\n' + cfg.artifactBodies : '')
  : '';

const historyText = historyItems.length
  ? '\n\n--- Histórico ---\n' +
    historyItems.map(m => (m.role === 'user' ? 'Usuário' : 'Assistente') + ': ' + m.content).join('\n') +
    '\n--- Fim do histórico ---'
  : '';

return [{
  json: {
    question: cfg.question,
    systemPromptWithContext:
      cfg.systemPrompt + '\n\n' + cfg.modeGuidance + historyText +
      '\n\nTrechos dos documentos:\n\n' + context + artifactState + semFonte,
    chunks, // vai para o 'Code: Parseia Citações'
    conversationId: cfg.conversationId,
    userId: cfg.userId,
    mode: cfg.mode,
    supabaseUrl: cfg.supabaseUrl,
    supabaseServiceKey: cfg.supabaseServiceKey,
  }
}];

const d = $input.first().json;
const mode = d.mode;

const topK      = mode === 'pesquisa' ? 30 : 12;
const maxTokens = mode === 'pesquisa' ? 2600 : 700;

const modeGuidance = mode === 'pesquisa'
  ? 'MODO PESQUISA: você recebeu trechos de várias buscas relacionadas. ' +
    'Compare o que as fontes dizem, aponte convergências e divergências, e ' +
    'organize em seções com subtítulos. Quando duas fontes discordarem, ' +
    'mostre as duas em vez de escolher uma em silêncio.'
  : 'MODO RÁPIDO: responda em até 4 parágrafos curtos, direto ao ponto. ' +
    'Sem introdução, sem recapitular a pergunta. Se o assunto for mais ' +
    'profundo do que cabe aqui, diga numa linha que vale usar o modo pesquisa.';

return [{ json: { ...d, topK, maxTokens, minSimilarity: 0.25, modeGuidance } }];

// Webhook v2 envolve o payload em .body — suporta os dois formatos
const raw = $input.first().json;
const d = raw.body || raw;

if (!d.question || String(d.question).trim().length < 3) {
  throw new Error('question é obrigatório (mínimo 3 caracteres)');
}

function uuid() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
    const r = Math.random() * 16 | 0;
    return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16);
  });
}

return [{
  json: {
    conversationId: d.conversationId || uuid(),
    isNewConversation: !d.conversationId,
    question: String(d.question).trim(),
    folderIds: Array.isArray(d.folderIds) ? d.folderIds : [],
    mode: d.mode || 'rapido',
    userId: d.userId || null,
    artifactOutline: d.artifactOutline || '',
    artifactBodies: d.artifactBodies || '',
    history: Array.isArray(d.history) ? d.history : [],  
    // === CONFIGS SUPABASE (usadas no HTTP: Busca Chunks) — ROTACIONE ESSA KEY ===
    supabaseUrl: 'https://alrnajijumqvxzmogwpy.supabase.co',
    supabaseServiceKey: '***REMOVIDO***',
  }
}];

